package controller;
import javafx.animation.*;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.VBox;import javafx.util.Duration;import model.*;import service.*;
public final class FinalQuizController {@FXML private Label questionNumber,timerLabel,question,feedback,scoreLabel;@FXML private VBox choices;@FXML private ProgressBar progress,timer;private Quiz quiz;private Timeline clock;private int seconds;
 @FXML public void initialize(){quiz=GameManager.getInstance().startFinalQuiz();showQuestion();}
 private void showQuestion(){if(quiz.isFinished()){finish();return;}Question q=quiz.current();questionNumber.setText("SECURITY QUESTION "+(quiz.getIndex()+1)+" / "+quiz.size());progress.setProgress((double)quiz.getIndex()/quiz.size());question.setText(q.prompt());feedback.setText("");feedback.getStyleClass().removeAll("success","warning");choices.getChildren().clear();for(int i=0;i<q.choices().size();i++){Button b=new Button(q.choices().get(i));b.getStyleClass().add("answer-button");b.setMaxWidth(Double.MAX_VALUE);int choice=i;b.setOnAction(e->answer(choice));choices.getChildren().add(b);}seconds=20;timer.setProgress(1);timerLabel.setText("20 s");if(clock!=null)clock.stop();clock=new Timeline(new KeyFrame(Duration.seconds(1),e->{seconds--;timer.setProgress(seconds/20.0);timerLabel.setText(seconds+" s");if(seconds<=0)answer(-1);}));clock.setCycleCount(20);clock.play();}
 private void answer(int selected){clock.stop();Question answeredQuestion=quiz.current();for(int i=0;i<choices.getChildren().size();i++){Button choice=(Button)choices.getChildren().get(i);choice.setDisable(true);if(i==answeredQuestion.correctIndex())choice.getStyleClass().add("answer-correct");else if(i==selected)choice.getStyleClass().add("answer-incorrect");}boolean correct=quiz.answer(selected);GameManager.getInstance().recordAnswer(correct);feedback.setText(correct?"Access fragment accepted.":"Access denied. "+answeredQuestion.explanation());feedback.getStyleClass().add(correct?"success":"warning");scoreLabel.setText("XP  "+GameManager.getInstance().getPlayer().getScore());PauseTransition pause=new PauseTransition(Duration.millis(1100));pause.setOnFinished(e->showQuestion());pause.play();}
 private void finish(){progress.setProgress(1);if(quiz.getCorrect()==quiz.size())GameManager.getInstance().getPlayer().unlock(Achievement.WATER_GENIUS);SceneManager.switchScene("Result.fxml");}}
